#!/usr/bin/env node
// Build-time only. Runtime hosts consume fixed generated bytes, never WAT.
import { readFile, writeFile, mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";

const args = process.argv.slice(2);
if (args.length > 1 || (args.length === 1 && args[0] !== "--check"))
  throw new Error("Usage: node host/scripts/generate-snapshot-comparator.mjs [--check]");
if (!process.env.KANDELO_DEV_SHELL_TOOL_PATH)
  throw new Error("Run with repository scripts/dev-shell.sh and its declared wat2wasm");
const check = args[0] === "--check";
const templatePath = new URL("./snapshot-comparator.wat", import.meta.url);
const outputPath = new URL("../src/generated/process-snapshot-comparator-bytes.ts", import.meta.url);
const template = await readFile(templatePath, "utf8");
const generator = await readFile(new URL(import.meta.url));
const sha256 = bytes => createHash("sha256").update(bytes).digest("hex");
const memoryType = (width, shared) => `${width === 8 ? "i64 " : ""}0${shared ? " 65536 shared" : ""}`;
const address = (width, base) => {
  const wide = `(i64.add (local.get $${base}) (local.get $offset))`;
  return width === 4 ? `(i32.wrap_i64 ${wide})` : wide;
};
const vectorLoop = `
    (block $vectors_done
      (loop $vectors
        (br_if $vectors_done
          (i64.lt_u
            (i64.sub (local.get $length) (local.get $offset))
            (i64.const 16)))
        (if (v128.any_true
              (v128.xor
                (v128.load $kernel align=1 @KERNEL_ADDRESS@)
                (v128.load $process align=1 @PROCESS_ADDRESS@)))
          (then (return (i32.const 1))))
        (local.set $offset (i64.add (local.get $offset) (i64.const 16)))
        (br $vectors)))`;
// WHY: large unchanged mappings pay one branch per vector in the tail loop.
// Combine four vector differences before testing, with the entire 64-byte
// block proved present first. OR preserves duplicate differences; XOR would
// cancel them. The original vector/word/byte tails still handle short spans.
const simdLoop = `
    (block $blocks_done
      (loop $blocks
        (br_if $blocks_done
          (i64.lt_u
            (i64.sub (local.get $length) (local.get $offset))
            (i64.const 64)))
        (if (v128.any_true
              (v128.or
                (v128.or
                  (v128.xor
                    (v128.load $kernel offset=0 align=1 @KERNEL_ADDRESS@)
                    (v128.load $process offset=0 align=1 @PROCESS_ADDRESS@))
                  (v128.xor
                    (v128.load $kernel offset=16 align=1 @KERNEL_ADDRESS@)
                    (v128.load $process offset=16 align=1 @PROCESS_ADDRESS@)))
                (v128.or
                  (v128.xor
                    (v128.load $kernel offset=32 align=1 @KERNEL_ADDRESS@)
                    (v128.load $process offset=32 align=1 @PROCESS_ADDRESS@))
                  (v128.xor
                    (v128.load $kernel offset=48 align=1 @KERNEL_ADDRESS@)
                    (v128.load $process offset=48 align=1 @PROCESS_ADDRESS@)))))
          (then (return (i32.const 1))))
        (local.set $offset (i64.add (local.get $offset) (i64.const 64)))
        (br $blocks)))` + vectorLoop;
const variants = [];
const directory = await mkdtemp(join(tmpdir(), "kandelo-snapshot-comparator-"));
try {
  for (const kernelWidth of [4, 8]) for (const kernelShared of [false, true])
    for (const processWidth of [4, 8]) for (const processShared of [false, true])
      for (const mode of ["scalar", "simd"]) {
        const key = `k${kernelWidth * 8}${kernelShared ? "s" : "u"}-p${processWidth * 8}${processShared ? "s" : "u"}-${mode}`;
        const wat = template.replaceAll("@SIMD_LOOP@", mode === "simd" ? simdLoop : "")
          .replaceAll("@KERNEL_MEMORY_TYPE@", memoryType(kernelWidth, kernelShared))
          .replaceAll("@PROCESS_MEMORY_TYPE@", memoryType(processWidth, processShared))
          .replaceAll("@KERNEL_ADDRESS@", address(kernelWidth, "snapshot"))
          .replaceAll("@PROCESS_ADDRESS@", address(processWidth, "source"));
        if (/@[A-Z_]+@/.test(wat)) throw new Error("Unresolved comparator template token: " + key);
        // The fixed template has no side-effecting instructions or segments.
        // Root's binary structural controls must also inspect emitted modules.
        const code = wat.replace(/;;[^\n]*/g, "");
        if (/\((?:start|data|elem)\b|\b(?:memory\.(?:grow|copy|fill|init)|[\w.]*store[\w.]*|[\w.]*atomic[\w.]*)\b/.test(code))
          throw new Error("Forbidden comparator operation: " + key);
        const input = join(directory, key + ".wat"), output = join(directory, key + ".wasm");
        await writeFile(input, wat);
        const compiled = spawnSync("wat2wasm", ["--enable-all", input, "-o", output],
          { encoding: "utf8", timeout: 30000, maxBuffer: 1024 * 1024 });
        if (compiled.error || compiled.status !== 0)
          throw new Error(`wat2wasm ${key}: ${compiled.error?.message ?? compiled.signal ?? compiled.status}\n${compiled.stdout ?? ""}${compiled.stderr ?? ""}`);
        const bytes = await readFile(output);
        if (!bytes.length || bytes.length > 4096) throw new Error("Unexpected comparator size: " + key);
        variants.push({ key, bytes, sha256: sha256(bytes) });
      }
  if (variants.length !== 32) throw new Error("Expected all 32 fixed comparator variants");
  let generated = "// Generated by host/scripts/generate-snapshot-comparator.mjs; do not edit.\n";
  generated += "// Run under the declared devshell; --check compiles into temporary files only.\n";
  generated += `export const SNAPSHOT_COMPARATOR_GENERATOR_SHA256 = ${JSON.stringify(sha256(generator))};\n`;
  generated += `export const SNAPSHOT_COMPARATOR_TEMPLATE_SHA256 = ${JSON.stringify(sha256(template))};\n`;
  generated += "export const SNAPSHOT_COMPARATOR_BYTES: Readonly<Record<string, readonly number[]>> = Object.freeze({\n";
  for (const { key, bytes, sha256: digest } of variants) {
    generated += `  // sha256 ${digest}\n  ${JSON.stringify(key)}: Object.freeze([\n`;
    for (let at = 0; at < bytes.length; at += 24)
      generated += "    " + [...bytes.subarray(at, at + 24)].map(value => "0x" + value.toString(16).padStart(2, "0")).join(", ") + ",\n";
    generated += "  ]),\n";
  }
  generated += "});\n";
  if (check) {
    const existing = await readFile(outputPath, "utf8");
    if (existing !== generated) throw new Error("Generated comparator bytes differ: " + fileURLToPath(outputPath));
    process.stdout.write("Comparator generated bytes match (32 variants).\n");
  } else {
    await writeFile(outputPath, generated);
    process.stdout.write("Generated 32 fixed snapshot comparator modules.\n");
  }
} finally {
  await rm(directory, { recursive: true, force: true });
}
